CustomField.formula:
IF( CONTAINS( MailingStreet, SUBSTITUTE($Label.iWave_PROscores__NewLine,"-", "") ),
LEFT( MailingStreet,    
           FIND( SUBSTITUTE($Label.iWave_PROscores__NewLine,"-", ""), 
                MailingStreet)   
                /* If you use MID, add -2 to remove the 2 ghost characters that you need to trim off */
   ),
   MailingStreet
)
